        self.assertEqual(render(r"\q \< \="), "<p>\\q &lt; =</p>")
        self.assertEqual(render(r"*a\*b*"), "<p><strong>a*b</strong></p>")
        self.assertEqual(render(r"*a\* b*"), "<p><strong>a* b</strong></p>")
